  'settings.diagnosisRuns': 'ರೋಗನಿರ್ಣಯ ವಿಶ್ಲೇಷಣೆಗಳು',
  'settings.rateLimited': 'ಸೇವೆಯನ್ನು ನ್ಯಾಯಯುತವಾಗಿಡಲು ವೇಗ-ಮಿತಿ ಹೊಂದಿದೆ',
  'settings.smsDelivery': 'SMS ವಿತರಣೆ',
  'settings.currentlySimulated': 'ಪ್ರಸ್ತುತ ಅನುಕರಣೆ (ಸಿಮ್ಯುಲೇಶನ್)',
  'settings.signOutAria': 'AgriN‌ನಿಂದ ನಿರ್ಗಮಿಸಿ',
  'settings.signOut': 'ನಿರ್ಗಮಿಸಿ',
  'settings.language': 'ಭಾಷೆ',
  'settings.languageCopy':
    'AgriN ಮಾರ್ಗದರ್ಶನ ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ಬರೆಯಲ್ಪಟ್ಟು ನೀವು ಆಯ್ಕೆಮಾಡುವ ಭಾಷೆಗೆ ಭಾಷಾಂತರವಾಗುತ್ತದೆ. ನಿಮ್ಮ ಆಯ್ಕೆ ಹೊಸ ಸ್ಕ್ಯಾನ್‌ಗಳಿಗೆ ಡೀಫಾಲ್ಟ್ ಮಾರ್ಗದರ್ಶನ ಭಾಷೆಯಾಗುತ್ತದೆ.',
  'settings.languageFooter':
    'ಎಲ್ಲಾ ಒಂಬತ್ತು ಭಾಷೆಗಳೂ ಲಭ್ಯವಿವೆ. ಧ್ವನಿ ಲಭ್ಯತೆ ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಸ್ಥಾಪಿಸಿರುವ ಪಠ್ಯ-ಧ್ವನಿ (TTS) ಧ್ವನಿಗಳ ಮೇಲೆ ಅವಲಂಬಿಸಿರುತ್ತದೆ.',
  'settings.notifications': 'ಅಧಿಸೂಚನೆಗಳು',
  'settings.notificationsCopy':
    'SMS ವಿತರಣೆ ಸದ್ಯ ಅನುಕರಣೆಯಲ್ಲಿದೆ — ನಿಜವಾದ SMS ಗೇಟ್‌ವೇ ಜೋಡಿಸುವವರೆಗೆ ನಿಮ್ಮ ಫಲಿತಾಂಶ ಅದನ್ನು ಅನುಕರಣೆ ಎಂದು ಗುರುತಿಸುತ್ತದೆ.',
  'settings.audio': 'ಆಡಿಯೋ',
  'settings.audioCopy':
    "ಮಾರ್ಗದರ್ಶನ ಆಡಿಯೋ ನಿಮ್ಮ ಸಾಧನದ ಅಂತರ್ನಿರ್ಮಿತ ಪಠ್ಯ-ಧ್ವನಿ ಧ್ವನಿಯನ್ನು, ನೀವು ಫಲಿತಾಂಶದಲ್ಲಿ ಆಯ್ಕೆಮಾಡುವ ಭಾಷೆಯಲ್ಲಿ ಬಳಸುತ್ತದೆ. ಆ ಭಾಷೆಯ ಧ್ವನಿ ಸ್ಥಾಪಿಸದಿದ್ದರೆ, ಮಾತನಾಡುವಂತೆ ನಟಿಸುವ ಬದಲು AgriN ಅದನ್ನು ಹೇಳುತ್ತದೆ.",
  'settings.privacy': 'ಗೌಪ್ಯತೆ',
  'settings.privacyCopy':
    'ನಿಮ್ಮ ಫೋಟೋಗಳು ಮತ್ತು ಸ್ಕ್ಯಾನ್ ಇತಿಹಾಸ ನಿಮ್ಮ ಖಾತೆಗೆ ಖಾಸಗಿ. ಸ್ಕ್ಯಾನ್ ನಡೆಯುತ್ತಿರುವಾಗ ಮಾತ್ರ ಫೋಟೋ ಸರ್ವರ್-ಬದಿಯ AI ಮಾದರಿಗೆ ಹೋಗುತ್ತದೆ — ಬೇರೆಲ್ಲಿಯೂ ಅಲ್ಲ.',
  'settings.about': 'ಬಗ್ಗೆ',
  'settings.aboutCopy':
    'AgriN ರೋಗ ಮಾರ್ಗದರ್ಶನವನ್ನು AI ಮಾದರಿ ರಚಿಸುತ್ತದೆ ಮತ್ತು ಅದು ಕೇವಲ ಸಲಹೆ. ರೋಗನಿರ್ಣಯಗಳು ನಿಮ್ಮ ಖಾಸಗಿ ಬೆಳೆ ಇತಿಹಾಸದಲ್ಲಿ ಉಳಿಯುತ್ತವೆ.',
  'settings.aboutVersion': 'AgriN · ಆವೃತ್ತಿ {version}',
  'home.heroEyebrow': 'ಬೆಳೆ ಆರೋಗ್ಯ ಸಹಾಯಕ',
  'home.heroTitle': 'ನಿಮ್ಮ ಬೆಳೆಗೆ ಏನಾಗುತ್ತಿದೆ ಎಂಬುದನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಿ.',
  'home.heroCopy':
    'AgriN ಸಾಮಾನ್ಯ ಭಾರತೀಯ ಬೆಳೆಗಳ ಆರೋಗ್ಯವನ್ನು ಪರಿಶೀಲಿಸಲು ನೆರವಾಗುತ್ತದೆ — ಟಮಾಟೊ, ಮೆಣಸಿನಕಾಯಿ, ಗದ್ದೆ (ಪ್ಯಾಡಿ), ಹತ್ತಿ, ಸೋಯಾಬೀನ್, ಗೋಧಿ, ಜೋಳ, ನೆಲಗಡಲೆ, ಕಬ್ಬು ಮತ್ತು ಈರುಳ್ಳಿ. ಎಲೆಯನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಿ, ಸ್ಪಷ್ಟ ರೋಗನಿರ್ಣಯ ಪಡೆಯಿರಿ, ಮತ್ತು ಮುಂದೆ ಏನು ಮಾಡಬೇಕೆಂದು ನಿಖರವಾಗಿ ತಿಳಿಯಿರಿ — ಸರಳ ಭಾಷೆಯಲ್ಲಿ, ನೀವು ಆಯ್ಕೆಮಾಡುವ ಭಾಷೆಯಲ್ಲಿ.',
