  'home.howTitle': 'ಸ್ಕ್ಯಾನ್, ಅರ್ಥಮಾಡಿ, ಕ್ರಿಯೆ, ಟ್ರ್ಯಾಕ್',
  'home.howDescription': 'ಒಂದು ಸಮಯದಲ್ಲಿ ಒಂದು ಬೆಳೆ — AI ವಿಜೆಟ್‌ಗಳ ಪ್ರವಾಹವಲ್ಲ, ಶಾಂತ, ಪ್ರಾಯೋಗಿಕ ಚಕ್ರ.',
