  'home.loopMonitorTitle': 'ಟ್ರ್ಯಾಕ್',
  'home.loopMonitorCopy':
    'ಕಾಲಕ್ರಮೇಣ ನಿಮ್ಮ ಸ್ಕ್ಯಾನ್‌ಗಳನ್ನು ಬೆಳೆ ಆರೋಗ್ಯ ವಿಭಾಗವು ಗುಂಪು ಮಾಡುತ್ತದೆ, ಆದ್ದರಿಂದ ಬೆಳೆ ಹೇಗೆ ಮುನ್ನಡೆಯುತ್ತಿದೆ ಎಂದು ನೋಡಬಹುದು.',
