  'home.emptyDescription':
    'ನಿಮ್ಮ ಮೊದಲ ಸ್ಕ್ಯಾನ್ ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ. ನಿಮ್ಮ ಬೆಳೆಯ ಆರೋಗ್ಯದ ಚಿತ್ರ ರೂಪಿಸಲು ಎಲೆಯನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡುವ ಮೂಲಕ ಪ್ರಾರಂಭಿಸಿ.',
