  'scan.know2': 'ಫೋಟೋಗಳು ನಿಮ್ಮ ಖಾತೆಗೆ ಖಾಸಗಿಯಾಗಿರುತ್ತವೆ ಮತ್ತು ಹಂಚಿಕೆಯಾಗುವುದಿಲ್ಲ.',
