  'scan.rateLimited': 'ಎಲ್ಲರ ಸುರಕ್ಷತೆಗಾಗಿ ಸ್ಕ್ಯಾನ್‌ಗಳಿಗೆ ವೇಗ-ಮಿತಿ ಹೊಂದಿಸಲಾಗಿದೆ.',
  'scan.errNoPhoto': 'ಸ್ಕ್ಯಾನ್ ಮಾಡಲು ಎಲೆಯ ಫೋಟೋ ಆಯ್ಕೆಮಾಡಿ.',
  'scan.errConnecting': 'ನಿಮ್ಮ ಸ್ಕ್ಯಾನ್ ಸೆಷನ್ ಇನ್ನೂ ಸಂಪರ್ಕಗೊಳ್ಳುತ್ತಿದೆ. ದಯವಿಟ್ಟು ಮರುಲೋಡ್ ಮಾಡಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
