  'result.trust':
    'ಈ ಫಲಿತಾಂಶವನ್ನು ನೀವು ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ಫೋಟೋದಿಂದ, ಸಾಮಾನ್ಯ ಬೆಳೆ ಆರೈಕೆಗಾಗಿ AI ಮಾದರಿ ರಚಿಸಿತು. ಮಣ್ಣು, ಹವಾಮಾನ ಮತ್ತು ಸ್ಥಳೀಯ ಪರಿಸ್ಥಿತಿಗಳು ಭಿನ್ನ — ಇದನ್ನು ಆರಂಭಿಕ ಹಂತವಾಗಿ ಪರಿಗಣಿಸಿ ಮತ್ತು ಯಾವುದೇ ಚಿಕಿತ್ಸೆಯನ್ನು ನಿಮ್ಮ ಸ್ಥಳೀಯ ಕೃಷಿ ವಿಸ್ತರಣಾ ಅಧಿಕಾರಿಯೊಂದಿಗೆ ದೃಢಪಡಿಸಿ.',
