  'land.storyCopy':
    'जवळजवळ प्रत्येक पीक समस्या दिसणाऱ्या एखाद्या गोष्टीपासून — डाग, रंग बदलणे, वाकणे, मुरडणे, किंवा जखम — सुरू होते. AgriN त्या दिसणाऱ्या संकेतापासून सुरू होते आणि त्याचे सोप्या भाषेतील मूल्यांकन व व्यावहारिक मार्गदर्शनात रूपांतर करते.',
