  'result.trust':
    'ఈ ఫలితం మీరు అప్లోడ్ చేసిన ఫోటో నుండి, సాధారణ పంట సంరక్షణ కోసం AI మోడల్ ద్వారా రూపొందించబడింది. నేల, వాతావరణం మరియు స్థానిక పరిస్థితులు భిన్నంగా ఉంటాయి — దీన్ని ప్రారంభ స్థానంగా పరిగణించండి మరియు ఏదైనా చికిత్సను మీ స్థానిక వ్యవసాయ విస్తరణ అధికారితో నిర్ధారించండి.',
