  'land.eyebrow': 'AI-ఆధారిత పంట ఆరోగ్య తోడు',
  'land.heroTitle': 'మీ పంట మీకు ఏమి చెబుతుందో అర్థం చేసుకోండి.',
  'land.heroSub':
    'ప్రభావిత ఆకు ఫోటో తీయండి. AgriN — మీ భాషలో — అది ఎలా కనిపిస్తుందో, తర్వాత ఏమి చేయాలో AI సహాయంతో వివరిస్తుంది.',
  'land.ctaExplore': 'AgriN అన్వేషించండి',
  'land.heroShow': 'ఫోటో {n} చూపించు',
  'land.heroCounter': '{current} / {total}',
  'land.storyEyebrow': 'ఎందుకు AgriN',
  'land.storyTitle': 'పంట సమస్యలు సాధారణంగా ఎలా గుర్తించబడతాయో దాని చుట్టూ నిర్మించబడింది.',
  'land.storyCopy':
    'దాదాపు ప్రతి పంట సమస్య మీకు కనిపించే దానితో మొదలవుతుంది — మచ్చ, రంగు మారడం, వంకర, వాడిపోవడం, లేదా గాయం. AgriN ఆ కనిపించే సంకేతం నుండి మొదలై దాన్ని సరళ భాషలో విశ్లేషణగా, ఆచరణాత్మక మార్గదర్శకంగా మారుస్తుంది.',
  'land.storyList1': 'ఆకు ఫోటోతో ప్రారంభించండి',
  'land.storyList2': 'సరళ భాషలో విశ్లేషణ పొందండి',
  'land.storyList3': 'స్పష్టమైన, ఆచరణాత్మక తదుపరి దశలను చదవండి',
  'land.worksTitle': 'స్కాన్, అర్థం, చర్య, పర్యవేక్షణ',
  'land.worksCopy': 'ఐదు చిన్న దశలు, ఒకేసారి ఒక పంట.',
  'land.how1Copy': 'AgriN కు తెలిసిన పంటల నుండి ఎంచుకోండి — టమోటా, మిరప, వరి, పత్తి మరియు మరిన్ని.',
  'land.how2Copy': 'ప్రభావిత ఆకు స్పష్టమైన ఫోటో జోడించండి. మంచి వెలుతురు, నిలకడగా ఉండే చేయి సహాయం చేస్తాయి.',
  'land.how3Title': 'ఫలితాన్ని అర్థం చేసుకోండి',
  'land.how3Copy': 'సంభావ్య స్థితి, ఫోటో నుండి చదివిన సంకేతాలు మరియు విశ్వాస స్థాయిని చూడండి.',
  'land.how4Title': 'మార్గదర్శకం ప్రకారం చర్య తీసుకోండి',
  'land.how4Copy': 'మీ భాషలో దశలవారీ సలహా పొందండి — చదవండి లేదా వినండి.',
  'land.how5Title': 'పర్యవేక్షణ కొనసాగించండి',
  'land.how5Copy': 'మీ స్కాన్లు మీరు వెనక్కి చూడగలిగే ప్రైవేట్ పంట చరిత్రను నిర్మిస్తాయి.',
  'land.capTitle': 'AgriN దేనిలో సహాయం చేయగలదు',
  'land.capCopy': 'కేంద్రీకృత సామర్థ్యాలు — అతిశయం లేదు.',
  'land.cap1Title': 'AI-సహాయ ఆరోగ్య విశ్లేషణ',
  'land.cap1Copy': 'ఆకు ఫోటో తీయండి, విశ్లేషణ పొందండి, గుర్తించిన సంకేతాలు చూడండి, ఆచరణాత్మక తదుపరి దశలు చదవండి.',
  'land.cap2Title': 'మీ భాషలో మార్గదర్శకం',
  'land.cap2Copy': 'తొమ్మిది భాషలు, మీ పరికరంలో సరైన వాయిస్ ఉంటే ఐచ్ఛిక వాయిస్తో.',
  'land.cap3Title': 'పంట ఆరోగ్యం, కలిసి ఉంచబడింది',
  'land.cap3Copy': 'ప్రతి స్కాన్ మీ ప్రైవేట్ చరిత్రలో ఉంటుంది, కాబట్టి పంట ఎలా పురోగమిస్తోందో చూడవచ్చు.',
  'land.langEyebrow': 'బహుభాషా',
  'land.langTitle': 'మీ భాష మాట్లాడే మార్గదర్శకం.',
  'land.langCopy': 'AgriN ఇంగ్లీషులో చదివి, ప్రతి ఫలితాన్ని మీరు ఎంచుకున్న భాషలోకి అనువదిస్తుంది.',
  'land.langVoice': 'వాయిస్ ప్లేబ్యాక్ మీ పరికరంలో ఇన్స్టాల్ చేసిన భాషలను ఉపయోగిస్తుంది. వాయిస్ లేకపోతే AgriN నిజాయితీగా చెబుతుంది — నటించదు.',
  'land.monitorEyebrow': 'గమనిస్తూ ఉండండి',
  'land.monitorTitle': 'ఒకసారి స్కాన్ చేయండి — ఆపై గమనిస్తూ ఉండండి.',
  'land.monitorCopy':
    'AgriN స్కాన్-మరచిపో సాధనం కాదు. ప్రతి ఫలితం పంట వారీగా సమూహమై మీ ప్రైవేట్ పంట ఆరోగ్య పేజీలో సేవ్ అవుతుంది, కాబట్టి మార్పులు గమనించడం సులభం.',
  'land.monitorEmptyTitle': 'ఒక స్కాన్ తో ప్రారంభించండి',
  'land.monitorEmptyCopy': 'మీ మొదటి స్కాన్ మీ చరిత్రను సృష్టిస్తుంది. మీరు తీసే ప్రతి ఆకు ఫోటోతో అది నిజాయితీగా పెరుగుతుంది.',
