  'scan.know1': 'AI மாதிரி உங்கள் உலாவிக்கு ஒருபோதும் வெளிப்படாது — பகுப்பாய்வு சேவையக-பக்கமாக நடக்கிறது.',
  'scan.know2': 'புகைப்படங்கள் உங்கள் கணக்கிற்கு தனிப்பட்டவை மற்றும் பகிரப்படாது.',
  'scan.know3': 'முடிவுகள் ஆலோசனை; சிகிச்சையை உள்ளூர் அலுவலருடன் உறுதிப்படுத்துங்கள்.',
  'scan.rateLimited': 'அனைவரின் பாதுகாப்புக்காக ஸ்கேன்களுக்கு விகித-வரம்பு உள்ளது.',
  'scan.errNoPhoto': 'ஸ்கேன் செய்ய ஒரு இலை புகைப்படத்தைத் தேர்ந்தெடுங்கள்.',
  'scan.errConnecting': 'உங்கள் ஸ்கேன் அமர்வு இன்னும் இணைந்து வருகிறது. தயவுசெய்து மீண்டும் ஏற்றி முயற்சிக்கவும்.',
  'scan.errQuota': 'இந்த மணி நேர ஸ்கேன் வரம்பை அடைந்துவிட்டீர்கள். தயவுசெய்து சிறிது நேரத்தில் முயற்சிக்கவும்.',
