  'auth.forgotSent':
    'அந்த மின்னஞ்சலுக்கு கணக்கு இருந்தால், மீட்டமைப்பு இணைப்பு வழியில் உள்ளது. புதிய கடவுச்சொல்லை அமைக்க உங்கள் இன்பாக்ஸைச் சரிபார்க்கவும்.',
  'health.eyebrow': 'கண்காணிப்பு',
  'health.title': 'பயிர் ஆரோக்கியம்',
  'health.description':
    'உங்கள் உண்மையான ஸ்கேன்கள், பயிர் வாரியாக தொகுக்கப்பட்டவை — என்ன கண்டறியப்பட்டது, அதைப் பற்றி என்ன செய்தீர்கள். இங்கே உங்கள் சொந்த பதிவுகள் மட்டுமே தோன்றும்.',
