  'health.errorCopy': '{error} — இது பொதுவாக சேவை தற்காலிகமாக அணுக முடியாதது என்பதைக் குறிக்கிறது.',
  'health.emptyTitle': 'இன்னும் பயிர் வரலாறு இல்லை',
  'health.emptyDescription':
    'உங்கள் ஸ்கேன்கள் நடந்தவுடன் இங்கே தோன்றும். ஒவ்வொரு ஸ்கேனும் ஒரு தேதியில் கண்டறியப்பட்டவற்றின் உண்மையான பதிவைச் சேர்க்கிறது.',
