  'health.footerCopy':
    'இந்தப் பக்கம் ஒரு உண்மையான ஸ்கேன் மூலம் சேமிக்கப்பட்ட பதிவுகளை மட்டுமே காட்டுகிறது — மதிப்பீடுகள் அல்லது கணிப்புகள் இல்லை.',
