  'result.eyebrow': '{crop} · ஸ்கேன் முடிவு',
  'result.title': 'நாங்கள் கண்டறிந்ததே இது',
  'result.caveat':
    'AI-உதவி வழிகாட்டுதல் ஆலோசனை மட்டுமே — இது தொழில்முறை வேளாண் கண்டறிதல் அல்ல. எந்த சிகிச்சையையும் உங்கள் உள்ளூர் வேளாண் விரிவாக்க அலுவலருடன் உறுதிப்படுத்துங்கள்.',
  'result.diagnosis': 'கண்டறிதல்',
