  'result.whatToDo': 'இப்போது என்ன செய்ய வேண்டும்',
  'result.monitoring': 'கண்காணிப்பைத் தொடருங்கள்',
  'result.monitoringCopy':
    'இந்த ஸ்கேன் பயிர் ஆரோக்கியத்தில் சேமிக்கப்படுகிறது, அங்கு உங்கள் ஸ்கேன்கள் பயிர் வாரியாக தொகுக்கப்பட்டு ஒவ்வொரு பயிரும் காலப்போக்கில் எப்படிச் செல்கிறது என்பதைக் காட்டுகிறது.',
  'result.confidence': 'நம்பிக்கை: {value}',
  'result.photoAlt': 'இந்த முடிவின் அடிப்படையான {crop} இலை புகைப்படம்',
  'result.viewHealth': 'பயிர் ஆரோக்கியத்தைப் பார்க்க',
