  'result.couldNotLoad': '{language} இல் வழிகாட்டுதலை ஏற்ற முடியவில்லை. {message}',
  'result.playAria': '{language} ஆடியோவை இயக்கு',
  'result.stopAria': '{language} ஆடியோவை நிறுத்து',
  'result.play': 'ஆடியோ இயக்கு',
  'result.playing': 'இயங்குகிறது…',
  'result.voiceMissing':
    '{language} குரல் இந்த சாதனத்தில் நிறுவப்படவில்லை — மேலே உள்ள வழிகாட்டுதலை நீங்கள் படிக்கலாம்.',
  'result.audioUnavailable': 'இந்த சாதனத்தில் ஆடியோ இல்லை.',
  'result.smsSimulated':
    'SMS விநியோகம் உருவகப்படுத்தப்படுகிறது (செயலி இணைக்கப்படவில்லை). ஆலோசனை {to}க்கு அனுப்பப்பட்டிருக்கும்.',
  'result.smsSent': 'SMS {to}க்கு அனுப்பப்பட்டது.',
  'result.yourPhoneNumber': 'உங்கள் தொலைபேசி எண்',
  'result.trust':
    'இந்த முடிவு நீங்கள் பதிவேற்றிய புகைப்படத்திலிருந்து, பொது பயிர் பராமரிப்புக்காக AI மாதிரியால் உருவாக்கப்பட்டது. மண், வானிலை மற்றும் உள்ளூர் நிலைமைகள் வேறுபடுகின்றன — இதை ஆரம்பப் புள்ளியாகக் கருதுங்கள், எந்த சிகிச்சையையும் உங்கள் உள்ளூர் வேளாண் விரிவாக்க அலுவலருடன் உறுதிப்படுத்துங்கள்.',
  'result.scanAnother': 'மற்றொரு பயிரை ஸ்கேன் செய்யுங்கள்',
  'result.backHome': 'முகப்புக்குத் திரும்பு',
  'result.couldNotLoadFallback': 'AgriN வழிகாட்டுதலை ஏற்ற முடியவில்லை.',
