  'healthLabel.unrecognized': 'வடிவம் அடையாளம் காணப்படவில்லை',
  'settings.theme': 'தோற்றம்',
  'settings.themeCopy': 'இந்தச் சாதனத்தில் AgriN எப்படி இருக்க வேண்டும் எனத் தேர்ந்தெடுக்கவும்.',
  'settings.themeLight': 'லைட்',
  'settings.themeDark': 'டார்க்',
  'settings.themeSystem': 'சிஸ்டம்',
  'settings.themeHint': 'உங்கள் சாதன அமைப்பைப் பின்தொடரும்.',
  'land.eyebrow': 'AI-இயங்கும் பயிர் ஆரோக்கிய துணை',
  'land.heroTitle': 'உங்கள் பயிர் உங்களுக்கு என்ன சொல்கிறது என்பதைப் புரிந்து கொள்ளுங்கள்.',
  'land.heroSub':
    'பாதிக்கப்பட்ட இலையின் புகைப்படம் எடுக்கவும். AgriN — உங்கள் மொழியில் — அது எப்படி இருக்கிறது, அடுத்து என்ன செய்வது என்பதை AI உதவியுடன் விளக்குகிறது.',
  'land.ctaExplore': 'AgriN-ஐ ஆராயுங்கள்',
  'land.heroShow': 'புகைப்படம் {n} காட்டு',
  'land.heroCounter': '{current} / {total}',
  'land.storyEyebrow': 'ஏன் AgriN',
  'land.storyTitle': 'பயிர் பிரச்சனைகள் உண்மையில் எப்படி கவனிக்கப்படுகின்றனவோ அதைச் சுற்றி உருவாக்கப்பட்டது.',
  'land.storyCopy':
    'ஏறக்குறைய ஒவ்வொரு பயிர் பிரச்சனையும் பார்வைக்குத் தெரியும் ஒன்றிலிருந்து தான் ஆரம்பமாகிறது — புள்ளி, நிற மாற்றம், சுருள், வாடுதல், அல்லது புண். AgriN அந்தத் தெரியும் அறிகுறியிலிருந்து தொடங்கி, அதை எளிய மொழி மதிப்பீடாகவும் நடைமுறை வழிகாட்டலாகவும் மாற்றுகிறது.',
  'land.storyList1': 'இலையின் புகைப்படத்துடன் தொடங்குங்கள்',
  'land.storyList2': 'எளிய மொழியில் மதிப்பீடு பெறுங்கள்',
  'land.storyList3': 'தெளிவான, நடைமுறை அடுத்த படிகளைப் படியுங்கள்',
  'land.worksTitle': 'ஸ்கேன், புரிந்து கொள்ளுங்கள், செயல்படுங்கள், கண்காணியுங்கள்',
  'land.worksCopy': 'ஐந்து சிறிய படிகள், ஒரு நேரத்தில் ஒரு பயிர்.',
  'land.how1Copy': 'AgriN-க்குத் தெரிந்த பயிர்களிலிருந்து தேர்ந்தெடுக்கவும் — தக்காளி, மிளகாய், நெல், பருத்தி மற்றும் மேலும்.',
  'land.how2Copy': 'பாதிக்கப்பட்ட இலையின் தெளிவான புகைப்படத்தைச் சேர்க்கவும். நல்ல வெளிச்சமும் நிலையான கையும் உதவும்.',
  'land.how3Title': 'முடிவைப் புரிந்து கொள்ளுங்கள்',
  'land.how3Copy': 'சாத்தியமான நிலை, புகைப்படத்திலிருந்து படித்த அறிகுறிகள் மற்றும் நம்பிக்கை அளவைப் பார்க்கவும்.',
  'land.how4Title': 'வழிகாட்டலின்படி செயல்படுங்கள்',
  'land.how4Copy': 'உங்கள் மொழியில் படி-படியான ஆலோசனை பெறுங்கள் — படியுங்கள் அல்லது கேளுங்கள்.',
  'land.how5Title': 'கண்காணிப்பைத் தொடருங்கள்',
  'land.how5Copy': 'உங்கள் ஸ்கேன்கள் நீங்கள் பின்னர் பார்க்கக்கூடிய தனிப்பட்ட பயிர் வரலாற்றை உருவாக்குகின்றன.',
  'land.capTitle': 'AgriN எதில் உதவ முடியும்',
  'land.capCopy': 'குவிந்துள்ள திறன்கள் — அதிகப்படியான வாக்குறுதி இல்லை.',
  'land.cap1Title': 'AI உதவி ஆரோக்கிய மதிப்பீடு',
  'land.cap1Copy': 'இலையின் புகைப்படம் எடுக்கவும், மதிப்பீடு பெறவும், கண்டறிந்த அறிகுறிகளைப் பார்க்கவும், நடைமுறை அடுத்த படிகளைப் படிக்கவும்.',
  'land.cap2Title': 'உங்கள் மொழியில் வழிகாட்டல்',
