  'land.langCopy': 'AgriN ஆங்கிலத்தில் படித்து, ஒவ்வொரு முடிவையும் நீங்கள் தேர்ந்தெடுக்கும் மொழிக்கு மொழிபெயர்க்கிறது.',
  'land.langVoice': 'குரல் இயக்கம் உங்கள் சாதனத்தில் நிறுவப்பட்ட மொழிகளைப் பயன்படுத்துகிறது. குரல் இல்லை என்றால் AgriN அதை நேர்மையாகச் சொல்கிறது — நடிக்கவில்லை.',
