  'land.trust3': 'AgriN நோயறிதலுக்கு உத்தரவாதம் அளிக்காது, மேலும் மாடல் பயிற்சிக்கு தனிப்பட்ட தரவு பயன்படுத்தப்படுவதில்லை.',
