    "മാർഗ്ഗനിർദ്ദേശ ഓഡിയോ നിങ്ങളുടെ ഉപകരണത്തിന്റെ ബിൽറ്റ്-ഇൻ ടെക്സ്റ്റ്-ടു-സ്പീച്ച് ശബ്ദം, നിങ്ങൾ ഫലത്തിൽ തിരഞ്ഞെടുക്കുന്ന ഭാഷയിൽ ഉപയോഗിക്കുന്നു. ആ ഭാഷയുടെ ശബ്ദം ഇൻസ്റ്റാൾ ചെയ്തിട്ടില്ലെങ്കിൽ, സംസാരിക്കുന്നതുപോലെ നടിക്കുന്നതിന് പകരം AgriN അത് പറയുന്നു.",
  'settings.privacy': 'സ്വകാര്യത',
  'settings.privacyCopy':
    'നിങ്ങളുടെ ഫോട്ടോകളും സ്കാൻ ചരിത്രവും നിങ്ങളുടെ അക്കൗണ്ടിന് സ്വകാര്യമാണ്. സ്കാൻ നടക്കുമ്പോൾ മാത്രം ഒരു ഫോട്ടോ സെർവർ-സൈഡ് AI മോഡലിലേക്ക് പോകുന്നു — മറ്റെവിടെയും അല്ല.',
  'settings.about': 'കുറിച്ച്',
  'settings.aboutCopy':
    'AgriN രോഗ മാർഗ്ഗനിർദ്ദേശം ഒരു AI മോഡൽ സൃഷ്ടിക്കുന്നതും ഉപദേശം മാത്രവുമാണ്. നിർണ്ണയങ്ങൾ നിങ്ങളുടെ സ്വകാര്യ വിള ചരിത്രത്തിൽ സൂക്ഷിക്കുന്നു.',
  'settings.aboutVersion': 'AgriN · പതിപ്പ് {version}',
  'home.heroEyebrow': 'വിള ആരോഗ്യ കൂട്ടാളി',
  'home.heroTitle': 'നിങ്ങളുടെ വിളയ്ക്ക് എന്ത് സംഭവിക്കുന്നു എന്ന് മനസ്സിലാക്കുക.',
  'home.heroCopy':
    'AgriN സാധാരണ ഇന്ത്യൻ വിളകളുടെ ആരോഗ്യം പരിശോധിക്കാൻ സഹായിക്കുന്നു — തക്കാളി, മുളക്, നെല്ല്, പരുത്തി, സോയാബീൻ, ഗോതമ്പ്, ചോളം, നിലക്കടല, കരിമ്പ്, ഉള്ളി. ഒരു ഇല സ്കാൻ ചെയ്യുക, വ്യക്തമായ നിർണ്ണയം നേടുക, അടുത്തത് എന്തുചെയ്യണം എന്ന് കൃത്യമായി അറിയുക — ലളിത ഭാഷയിൽ, നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന ഭാഷയിൽ.',
