  'result.trust':
    'ഈ ഫലം നിങ്ങൾ അപ്‌ലോഡ് ചെയ്ത ഫോട്ടോയിൽ നിന്ന്, പൊതു വിള പരിചരണത്തിനായി ഒരു AI മോഡൽ സൃഷ്ടിച്ചതാണ്. മണ്ണ്, കാലാവസ്ഥ, പ്രാദേശിക അവസ്ഥകൾ വ്യത്യസ്തമാണ് — ഇതിനെ തുടക്ക ബിന്ദുവായി കരുതുക, ഏത് ചികിത്സയും നിങ്ങളുടെ പ്രാദേശിക കാർഷിക വിപുലീകരണ ഉദ്യോഗസ്ഥനുമായി സ്ഥിരീകരിക്കുക.',
