  'settings.audio': 'ઑડિઓ',
  'settings.audioCopy':
    "માર્ગદર્શન ઑડિઓ તમારા ઉપકરણનો બિલ્ટ-ઇન ટેક્સ્ટ-ટુ-સ્પીચ અવાજ, પરિણામ પર તમે પસંદ કરો તે ભાષામાં વાપરે છે. તે ભાષાનો અવાજ ઇન્સ્ટોલ ન હોય, તો બોલવાનો ઢોંગ કરવાને બદલે AgriN તે કહે છે.",
  'settings.privacy': 'ગોપનીયતા',
