  'home.heroCopy':
    'AgriN સામાન્ય ભારતીય પાકોના આરોગ્યની ચકાસણીમાં મદદ કરે છે — ટમેટા, મરચું, ચોખા, કપાસ, સોયાબીન, ઘઉં, મકાઈ, મગફળી, શેરડી અને ડુંગળી. એક પાન સ્કેન કરો, સ્પષ્ટ નિદાન મેળવો, અને આગળ શું કરવું તે ચોક્કસ જાણો — સાદી ભાષામાં, તમે પસંદ કરો તે ભાષામાં.',
